        "about.header": "VỀ CHÚNG TÔI",
        "about.home": "Trang Chủ",
        "about.dashboard": "Bảng Điều Khiển",
        "about.login": "Đăng Nhập",
        "about.hero_badge": "Về Chúng Tôi",
        "about.hero_title": "Kiến Tạo Tương Lai",
        "about.hero_title_highlight": "Bất Động Sản Số",
        "about.hero_desc": "SGS Land không chỉ là một nền tảng giao dịch. Chúng tôi là hệ điều hành thông minh giúp minh bạch hóa thị trường và tối ưu hóa mọi quyết định đầu tư.",
        "about.mission_title": "Sứ Mệnh",
        "about.mission_desc": "Minh bạch hóa thông tin, đơn giản hóa giao dịch và mang lại giá trị thực cho cộng đồng.",
        "about.vision_title": "Tầm Nhìn",
        "about.vision_desc": "Trở thành nền tảng PropTech số 1 Đông Nam Á, tích hợp AI toàn diện vào mọi quy trình.",
        "about.values_title": "Giá Trị Cốt Lõi",
        "about.values_desc": "Trung thực, Sáng tạo, Tận tâm và Công nghệ vị nhân sinh.",
        "about.stat_years": "Năm Kinh Nghiệm",
        "about.stat_agents": "Môi Giới Tin Dùng",
        "about.stat_listings": "Tin Đăng Xác Thực",
        "about.stat_txn": "Giá Trị Giao Dịch",
        "about.team_title": "Đội Ngũ Lãnh Đạo",
        "about.team_desc": "Những chuyên gia hàng đầu trong lĩnh vực Bất động sản và Công nghệ.",
        "about.timeline_title": "Hành Trình Phát Triển",
        "about.timeline_desc": "Từ đội nhóm tư vấn BĐS chuyên nghiệp đến nền tảng PropTech AI hàng đầu Việt Nam.",
        "about.cert_title": "Pháp Lý & Chứng Nhận",
        "about.cert_desc": "SGS LAND hoạt động minh bạch, đầy đủ pháp lý. GPKD số 0312960439 do Sở KH&ĐT TP.HCM cấp. Chứng chỉ hành nghề môi giới BĐS do Bộ Xây Dựng cấp cho toàn bộ đội ngũ tư vấn.",
        "about.press_title": "Đối Tác Phân Phối",
        "about.press_desc": "SGS LAND là đại lý phân phối ủy quyền của Novaland Group, Nam Long Group, Masterise Homes và 7+ chủ đầu tư lớn tại TP.HCM và vùng ven.",
        "about.philosophy_title": "Triết Lý Kinh Doanh",
        "about.philosophy_desc": "Mỗi quyết định đầu tư BĐS cần dựa trên dữ liệu thực tế, không phải cảm tính hay áp lực bán hàng. SGS LAND cam kết: Minh bạch thông tin — Chính xác định giá — Hiệu quả giao dịch.",
        "about.ceo_bio": "Ông Trần Minh Thiện là nhà sáng lập kiêm CEO của SGS LAND, với hơn 15 năm kinh nghiệm trong lĩnh vực đầu tư BĐS và tư vấn pháp lý tại TP.HCM. Tốt nghiệp Đại học Luật TP.HCM và có chứng chỉ môi giới BĐS do Bộ Xây Dựng cấp, ông Thiện đã trực tiếp tư vấn hơn 500 giao dịch nhà phố, biệt thự và căn hộ cao cấp. Trước khi sáng lập SGS LAND năm 2019, ông là Giám đốc Kinh doanh tại đại lý F1 Novaland (2017-2019), Trưởng nhóm tư vấn Vinhomes (2015-2017) và chuyên viên pháp lý tại Masterise Homes (2013-2015). Ông Thiện là người khởi xướng mô hình tư vấn BĐS dựa trên dữ liệu thực tế giao dịch — nền tảng cho engine AVM của SGS LAND.",
        "about.cto_bio": "Ông Nguyễn Hoàng Nam là Giám đốc Công nghệ của SGS LAND, người thiết kế và xây dựng toàn bộ hệ thống công nghệ từ nền móng. Với bằng Thạc sĩ Khoa học Máy tính từ Đại học Bách Khoa TP.HCM và 8 năm kinh nghiệm trong lĩnh vực AI/ML, ông Nam lãnh đạo đội ngũ kỹ sư xây dựng mô hình AVM — hệ thống định giá BĐS tự động sử dụng 9 hệ số và đạt độ chính xác ±4.8% MAPE trên tập 2.400+ giao dịch công chứng tại TP.HCM. Trước SGS LAND, ông từng là AI Engineer tại VNG Corporation (2016-2019) và Data Scientist tại một fintech startup Singapore (2019-2021). Ông Nam là tác giả thuật toán phân tích xu hướng giá theo vi mô địa lý được tích hợp trong SGS Định Giá AI™.",
        "about.coo_bio": "Bà Lê Thị Hoa là Giám đốc Vận hành của SGS LAND, người xây dựng mạng lưới hơn 15.000 môi giới tin dùng trên nền tảng. Với 12 năm kinh nghiệm quản lý chuỗi sàn giao dịch BĐS tại TP.HCM, bà Hoa phát triển hệ thống quy trình chất lượng giúp SGS LAND đạt tỷ lệ giao dịch thành công 94%. Trước đây, bà là Giám đốc Vận hành tại CBRE Vietnam chi nhánh TP.HCM (2014-2018) và Trưởng phòng Kinh doanh tại Savills Vietnam (2011-2014). Bà Hoa cũng là chủ nhiệm đề án Chuẩn hóa quy trình môi giới BĐS Việt Nam — tài liệu đào tạo được hơn 8.000 môi giới trên cả nước tham khảo.",
        "about.cta_title": "Sẵn sàng hợp tác cùng chúng tôi?",
        "about.cta_dashboard": "Đến Bảng Điều Khiển",
        "about.cta_contact": "Liên Hệ Ngay",

