        "about.hero_title_highlight": "Digital Real Estate",
        "about.hero_desc": "SGS Land is more than a transaction platform. We are an intelligent operating system that brings transparency to the market and optimizes every investment decision.",
        "about.mission_title": "Mission",
        "about.mission_desc": "Democratize information, simplify transactions, and deliver real value to the community.",
