        "about.timeline_title": "Our Journey",
        "about.timeline_desc": "From a professional real estate advisory team to Vietnam's leading AI PropTech platform.",
        "about.cert_title": "Legal & Certifications",
        "about.cert_desc": "SGS LAND operates with full legal compliance. Business Registration No. 0312960439 issued by HCMC Department of Planning and Investment. Real estate brokerage licenses issued by the Ministry of Construction for all consultants.",
        "about.press_title": "Distribution Partners",
        "about.press_desc": "SGS LAND is an authorized distribution agent of Novaland Group, Nam Long Group, Masterise Homes and 7+ major developers in HCMC and surrounding areas.",
        "about.philosophy_title": "Business Philosophy",
        "about.philosophy_desc": "Every real estate investment decision should be data-driven, not based on intuition or sales pressure. SGS LAND commits to: Information Transparency — Accurate Valuation — Efficient Transactions.",
        "about.ceo_bio": "Mr. Tran Minh Thien is the Founder and CEO of SGS LAND, with over 15 years of experience in real estate investment and legal consulting in Ho Chi Minh City. A graduate of HCMC University of Law with a Ministry of Construction brokerage certificate, he has personally advised on 500+ transactions. Before founding SGS LAND in 2019, he served as Sales Director at Novaland F1 agent (2017-2019), Head Consultant at Vinhomes (2015-2017) and Legal Specialist at Masterise Homes (2013-2015). He pioneered the data-driven real estate advisory model that underpins the SGS LAND AVM engine.",
        "about.cto_bio": "Mr. Nguyen Hoang Nam is the CTO of SGS LAND, who architected and built the entire technology stack from the ground up. With an MSc in Computer Science from Ho Chi Minh City University of Technology and 8 years of AI/ML experience, he led the team to build the AVM — achieving +/-4.8% MAPE accuracy on 2,400+ notarized transactions. Previously AI Engineer at VNG Corporation (2016-2019) and Data Scientist at a Singapore fintech startup (2019-2021).",
        "about.coo_bio": "Ms. Le Thi Hoa is the COO of SGS LAND, who built and manages the network of 15,000+ trusted brokers. With 12 years of experience managing brokerage chains in HCMC, she developed the quality systems that help SGS LAND achieve a 94% transaction success rate. Previously Operations Director at CBRE Vietnam HCMC (2014-2018) and Sales Manager at Savills Vietnam (2011-2014).",
        "about.cta_title": "Ready to partner with us?",
